import React, { useState } from 'react';
import 'react-image-lightbox/style.css';
import Lightbox from 'react-image-lightbox';

const LightboxGallery = ({ images, thumbAlt }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [photoIndex, setPhotoIndex] = useState(0);

  if (!images || images.length === 0) return null;

  const fullImages = images.map(img => process.env.PUBLIC_URL + '/images/' + img);

  return (
    <>
      <img
        src={fullImages[0]}
        alt={thumbAlt}
        className="project-image"
        style={{ cursor: 'pointer', maxWidth: '220px', minWidth: '120px' }}
        onClick={() => setIsOpen(true)}
      />
      {isOpen && (
        <Lightbox
          mainSrc={fullImages[photoIndex]}
          nextSrc={fullImages[(photoIndex + 1) % fullImages.length]}
          prevSrc={fullImages[(photoIndex + fullImages.length - 1) % fullImages.length]}
          onCloseRequest={() => setIsOpen(false)}
          onMovePrevRequest={() => setPhotoIndex((photoIndex + fullImages.length - 1) % fullImages.length)}
          onMoveNextRequest={() => setPhotoIndex((photoIndex + 1) % fullImages.length)}
        />
      )}
    </>
  );
};

export default LightboxGallery;
