import React from 'react';

import '../styles/App.css';
import LightboxGallery from '../components/LightboxGallery';

const projectsData = [
  {
    categoryTitle: 'Full Stack Web Applications',
    description: 'A collection of web applications demonstrating my skills in both front-end and back-end development.',
    projects: [
      {
        title: 'Django Book Store',
        description: 'A full-stack book store application built with Django. Users can browse books, view details, and manage their orders, showcasing skills in database integration, backend logic, and user authentication.',
  images: ['bookstore-1.png', 'bookstore-2.png', 'bookstore-3.png'],
        link: null
      },
      {
        title: 'React Travel App',
        description: 'A multi-page travel application built with React. Features include a destinations page and a gallery, highlighting skills in front-end routing, component-based architecture, and interactive UI design.',
  images: ['travel-1.png', 'travel-2.png', 'travel-3.png'],
        link: null
      },
    ],
  },
  {
    categoryTitle: 'Event Listing App',
    description: 'A mobile application built with React Native and Firebase that helps organizers post and manage events.',
    projects: [
      {
        title: 'Event Listing App',
        description: 'Users can filter events, RSVP, and save events to their calendar. This project demonstrates skills in mobile development, real-time database integration, and UI/UX design.',
  images: ['event-1.jpg', 'event-2.jpg', 'event-3.jpg', 'event-4.jpg', 'event-5.jpg'],
        link: 'https://github.com/Petercollins55/EventListingApp'
      },
    ],
  },
  {
    categoryTitle: 'Electronics & Embedded Systems',
    description: 'Projects demonstrating my hands-on skills in circuit design, firmware development, and hardware troubleshooting.',
    projects: [
      {
        title: 'Electronics & Embedded Systems Projects',
        description: 'Designed and fabricated PCB prototypes using CAD tools like Fusion 360, Eagle, and EasyEDA. Developed C/C++ firmware for microcontrollers on platforms like Arduino and Raspberry Pi, covering full-cycle execution from hardware integration to debugging.',
  images: ['electronics-1.jpg', 'electronics-2.jpg', 'electronics-3.jpg', 'electronics-4.jpg', 'electronics-5.jpg'],
        link: null
      },
    ],
  },
  {
    categoryTitle: 'Biomedical Engineering',
    description: 'Specialized experience in the repair and calibration of multi-brand medical equipment.',
    projects: [
      {
        title: 'Multi-Brand Medical Equipment Repair & Calibration',
        description: 'Provided technical support for a range of diagnostic and therapeutic devices (Immucor, Mindray, Behnk, Dirui). Tasks included fault diagnosis, component-level repair, and firmware updates. This role improved device uptime and reliability, reduced service delays, and supported compliance with safety standards.',
  images: ['biomedical-1.jpg', 'biomedical-2.jpg', 'biomedical-3.jpg'],
        link: null
      },
    ],
  },
];

const Projects = () => {
  return (
    <div className="content">
      <h1>My Projects</h1>
      <p>Here are some of the projects I've worked on, showcasing my skills in software and electronics.</p>
      <div className="projects-grid">
        {projectsData.map((category, index) => (
          <div key={index} className="project-category">
            <h2>{category.categoryTitle}</h2>
            <p>{category.description}</p>
            {category.projects.map((project, projIndex) => (
              <div key={projIndex} className="project-card">
                <h3>{project.title}</h3>
                <p>{project.description}</p>
                {project.link && (
                  <a href={project.link} target="_blank" rel="noopener noreferrer" className="project-link">
                    View Project
                  </a>
                )}
                <div className="project-images">
                  <LightboxGallery images={project.images} thumbAlt={`${project.title} screenshot`} />
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

export default Projects;